package com.nextaicommerce.platform.fba;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.test.util.ReflectionTestUtils;import com.nextaicommerce.platform.web.*;
class FbaSkuHistoryControllerTest {
 @Test void oldStoreDialogCannotReadCurrentAccountHistory(){var history=mock(FbaSkuShipmentHistory.class);var controller=new FbaShipmentsController(mock(FbaReadRepository.class),mock(WorkspaceAccessRepository.class));ReflectionTestUtils.setField(controller,"skuHistory",history);var session=new MockHttpSession();session.setAttribute(AccountSelectionController.TENANT_ID,UUID.randomUUID());session.setAttribute(AccountSelectionController.STORE_ID,UUID.randomUUID());assertThatThrownBy(()->controller.skuHistory("SKU",UUID.randomUUID(),session)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);verifyNoInteractions(history);}
 @Test void marketplaceAndTenantComeFromSelectedSession(){var history=mock(FbaSkuShipmentHistory.class);var workspace=mock(WorkspaceAccessRepository.class);var controller=new FbaShipmentsController(mock(FbaReadRepository.class),workspace);ReflectionTestUtils.setField(controller,"skuHistory",history);UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();var session=new MockHttpSession();session.setAttribute(AccountSelectionController.TENANT_ID,tenant);session.setAttribute(AccountSelectionController.STORE_ID,store);when(workspace.findConnection(tenant,store)).thenReturn(new WorkspaceAccessRepository.ConnectionIdentity(store,"AMAZON","US"));controller.skuHistory("SKU",store,session);verify(history).recent(tenant,store,"US","SKU");}
}
